const ahora = new Date();
ahora.setHours(0, 0, 0, 0);

const fechaFin = new Date();
fechaFin.setDate(ahora.getDate()+1);
fechaFin.setHours(23, 59, 59, 999);

//QUITAR LUEGO
const fechaInicio = new Date();
fechaInicio.setDate(ahora.getDate()+1);
fechaInicio.setHours(23, 59, 59, 999);

// Formato Skyia
const formatSkyia = (date) => {
  const d = String(date.getDate()).padStart(2, '0');
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const y = date.getFullYear();
  return `${d}/${m}/${y}`;
};

return [{
  json: {
    skyia: {
      desde: formatSkyia(fechaInicio),
      hasta: formatSkyia(fechaFin)
    },
    ghl: {
      startTime: fechaInicio.getTime(), // Milisegundos
      endTime: fechaFin.getTime()   // Milisegundos
    }
  }
}];

// 1. Configuración de Fecha (Mañana) y Rango
const hoy = new Date();
const mañana = new Date(hoy);
mañana.setDate(hoy.getDate() + 1);

const yyyy = mañana.getFullYear();
const mm = String(mañana.getMonth() + 1).padStart(2, '0');
const dd = String(mañana.getDate()).padStart(2, '0');
const fechaBusqueda = `${yyyy}-${mm}-${dd}`;

// CONFIGURACIÓN DE RANGO (Ajustar según horario de ejecución: 09:00-14:00 o 14:00-20:00)
const horaMin = "14:15"; 
const horaMax = "20:00"; 

// 2. Recopilar eventos de todos los nodos de GHL conectados
const nombresNodos = [
  "Get Events GHL meso",
  "Get Events GHL clientes",
  "Get Events GHL dermo",
  "Get Events GHL prp",
  "Get Events GHL controles",
  "Get Events GHL revisaciones"
];

let todosLosEventos = [];
nombresNodos.forEach(nombre => {
  try {
    const items = $(nombre).all();
    items.forEach(item => {
      const evs = item.json.events || [];
      todosLosEventos = todosLosEventos.concat(evs);
    });
  } catch (e) { /* Nodo omitido si no hay datos */ }
});

// 3. Filtrar por Fecha, Rango y Excluir Bloqueos
const filtrados = todosLosEventos.filter(e => {
  if (!e.startTime) return false;
  const [fecha, horaFull] = e.startTime.split('T');
  const hora = horaFull.substring(0, 5);
  return fecha === fechaBusqueda && 
         hora >= horaMin && 
         hora < horaMax && 
         !e.title.includes("Bloqueo");
});

// 4. LÓGICA DE DEDUPLICACIÓN (Evita repetición Interno/Externo)
const deduplicados = [];
const registrosVistos = new Set();

filtrados.forEach(e => {
  const hora = e.startTime.split('T')[1].substring(0, 5);
  // Creamos una clave única basada en HORA + TÍTULO (Nombre del paciente)
  const claveUnica = `${hora}_${e.title.trim()}`;

  if (!registrosVistos.has(claveUnica)) {
    registrosVistos.add(claveUnica);
    deduplicados.push(e);
  }
});

// 5. Ordenar cronológicamente
deduplicados.sort((a, b) => a.startTime.localeCompare(b.startTime));

// 6. Construir el Mensaje Final
if (deduplicados.length === 0) {
  return [{ json: { mensaje: `✅ No hay citas programadas para mañana ${dd}/${mm} en el bloque ${horaMin}-${horaMax}.`, enviar: false } }];
}

let texto = `*📅 RESUMEN DE CITAS - TARDE (${dd}/${mm})*\n`;
texto += `*Bloque:* ${horaMin} a ${horaMax}\n`;
texto += `----------------------------------\n\n`;

deduplicados.forEach(e => {
  const hora = e.startTime.split('T')[1].substring(0, 5);
  texto += `⏰ *${hora}* - ${e.title}\n`;
});


return [{ json: { mensaje: texto, enviar: true } }];

