// 1. Configuración de Fecha (Mañana) - Usando lógica de hoy + 1
const hoy = new Date();
const mañana = new Date(hoy);
mañana.setDate(hoy.getDate() + 1);

const yyyy = mañana.getFullYear();
const mm = String(mañana.getMonth() + 1).padStart(2, '0');
const dd = String(mañana.getDate()).padStart(2, '0');
const fechaMañana = `${yyyy}-${mm}-${dd}`;

// 2. Rango Horario (Ajustar según bloque: 09:00-14:15 o 14:15-20:00)
const horaMin = "14:15"; 
const horaMax = "20:00"; 

// 3. Diccionarios de Mapeo
const mapping = {
  "1": ["AUSENTE"], "2": ["CANCELADO"], "3": ["CONTROL PO", "ELECTRO"],
  "5": ["REVISACION 1", "REVISACION 2", "REVI 2° MTC"],
  "7": ["PRP", "PRP 1"],
  "10": ["MESOTERAPIA CAPILAR", "MESOTERAPIA 1", "MESOTERAPIA FOTOS", "MESOTERAPIA CONTROL", "MESOTERAPIA REFUERZO", "MESOTERAPIA CON CORTICOIDES", "MESOTERAPIA 1 PO", "MESOTERAPIA BONIFCADA"],
  "13": ["DERMOPIGMENTACION", "DERMOPIGMENTACIÓN", "MICROBLADING"]
};

const idToProf = { "1": "AUSENTES", "2": "CANCELADOS", "3": "CONTROL MÉDICO", "5": "CONSULTA", "7": "PRP", "10": "MESOTERAPIA", "13": "DERMOPIGMENTACION" };

const nombresNodos = [
  "Get Events GHL meso1",
  "Get Events GHL revisaciones1", "Get Events GHL dermo1", "Get Events GHL prp1", "Get Events GHL controles1"
];

let eventosEncontrados = [];
let debugLog = [];

nombresNodos.forEach(nombre => {
  try {
    const items = $(nombre).all();
    items.forEach(item => {
      const events = item.json.events || [];
      eventosEncontrados = eventosEncontrados.concat(events);
    });
  } catch (e) { debugLog.push(`Error en nodo ${nombre}: ${e.message}`); }
});

const unicos = [];
const vistos = new Set();

eventosEncontrados.forEach(e => {
  // --- CAPA DE FILTRADO REFORZADA ---
  // 1. Verificamos que existan los datos básicos
  if (!e.startTime || !e.title) return;

  // 2. RESTRICCIÓN DE ESTADO: Solo enviamos si es "confirmed"
  if (e.appointmentStatus !== "confirmed") return;

  // 3. EXCLUSIÓN DE BLOQUEOS: Ignoramos bloqueos manuales y técnicos
  const tituloUpper = e.title.toUpperCase();
  if (tituloUpper.includes("BLOQUEO") || tituloUpper.includes("OCUPADO SKYIA")) return;

  const [fecha, horaFull] = e.startTime.split('T');
  const hora = horaFull.substring(0, 5);

  // 4. FILTRO TEMPORAL
  if (fecha === fechaMañana && hora >= horaMin && hora < horaMax) {
    const key = `${e.contactId}_${hora}`;
    if (!vistos.has(key)) {
      vistos.add(key);

      // --- Lógica de Nombre (Capitalize) ---
      // 1. Tomamos lo que está antes del guion y quitamos espacios extra
      const nombreCompletoRaw = e.title.split('-')[0].trim();

      // 2. Formateamos cada palabra (Dozetas Walter Pablo)
      const nombreFormateado = nombreCompletoRaw
        .split(' ')
        .filter(word => word.length > 0) // Evita espacios dobles
        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
        .join(' ');

      let especialidadDetectada = "GENERAL";
      let idEncontrado = null;

      for (const [id, productos] of Object.entries(mapping)) {
        if (productos.some(prod => tituloUpper.includes(prod.toUpperCase()))) {
          idEncontrado = id;
          break;
        }
      }

      if (idEncontrado) especialidadDetectada = idToProf[idEncontrado];

      unicos.push({
        json: {
          contactId: e.contactId,
          nombre: nombreFormateado,
          hora: hora,
          fecha: `${dd}/${mm}/${yyyy}`,
          grupo: hora < "14:15" ? "mañana" : "tarde",
          especialidad: especialidadDetectada
        }
      });
    }
  }
});

// Depuración si no hay resultados
if (unicos.length === 0) {
  return [{ 
    json: { 
      status: "Sin citas confirmadas",
      buscandoFecha: fechaMañana,
      rango: `${horaMin} a ${horaMax}`,
      totalEventosGHL: eventosEncontrados.length,
      errores: debugLog 
    } 
  }];
}

return unicos;

